//! Regression tests for code generated by the derive macros.

use measured::metric::MetricFamilyEncoding;
use measured::{Counter, FixedCardinalityLabel, LabelGroup, MetricGroup};
use measured_prometheus_text::{BufferedOpenMetricsEncoder, BufferedTextEncoder};

#[allow(dead_code)]
type Result<T> = std::result::Result<T, ()>;
#[allow(dead_code)]
type Option = u8;

#[derive(FixedCardinalityLabel, Clone, Copy)]
enum Method {
    Get,
    Post,
}

#[test]
fn generated_paths_do_not_depend_on_the_callers_prelude() {
    #[derive(FixedCardinalityLabel, Clone, Copy)]
    enum Kind {
        A,
    }
    #[derive(LabelGroup)]
    #[label(set = Labels)]
    struct Label {
        kind: Kind,
    }
    #[derive(MetricGroup)]
    #[metric(new())]
    struct Metrics {
        requests: measured::CounterVec<Labels>,
    }
    let metrics = Metrics::new();
    metrics.requests.inc(Label { kind: Kind::A });
    let mut enc = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut enc).unwrap();
    assert_eq!(
        enc.finish(),
        "# TYPE requests counter\nrequests{kind=\"a\"} 1\n"
    );
}

#[test]
fn names_that_differ_only_in_case_remain_distinct() {
    #[derive(LabelGroup)]
    #[label(set = Labels)]
    struct Label {
        #[label(rename = "foo")]
        a: Method,
        #[label(rename = "FOO")]
        b: Method,
    }
    #[derive(MetricGroup, Default)]
    struct Metrics {
        #[metric(rename = "foo")]
        a: Counter,
        #[metric(rename = "FOO")]
        b: Counter,
        requests: measured::CounterVec<Labels>,
    }
    let metrics = Metrics::default();
    metrics.a.inc();
    metrics.b.inc_by(2);
    metrics
        .requests
        .inc(Label { a: Method::Get, b: Method::Post });
    let mut enc = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut enc).unwrap();
    assert_eq!(
        enc.finish(),
        "# TYPE foo counter\nfoo 1\n\n# TYPE FOO counter\nFOO 2\n\n# TYPE requests counter\nrequests{foo=\"get\",FOO=\"post\"} 1\n"
    );
}

#[test]
fn hidden_and_nonliteral_docs_preserve_literal_help() {
    #[derive(MetricGroup, Default)]
    struct Metrics {
        /// counts things
        #[doc(hidden)]
        #[doc = concat!("not", "literal")]
        requests_total: Counter,
    }
    let mut enc = BufferedTextEncoder::new();
    Metrics::default().collect_group_into(&mut enc).unwrap();
    assert_eq!(
        enc.finish(),
        "# HELP requests_total counts things\n# TYPE requests_total counter\nrequests_total 0\n"
    );
}

#[derive(MetricGroup)]
struct Units {
    #[metric(unit = "seconds")]
    request_duration_seconds_total: Counter,
}

#[derive(MetricGroup)]
struct NamespacedUnits {
    #[metric(namespace = "api")]
    requests: Units,
}

#[test]
fn derived_metric_unit_reaches_openmetrics_and_classic_encoders() {
    let metrics = NamespacedUnits {
        requests: Units {
            request_duration_seconds_total: Counter::new(),
        },
    };
    metrics.requests.request_duration_seconds_total.inc();

    let mut openmetrics = BufferedOpenMetricsEncoder::new();
    metrics.collect_group_into(&mut openmetrics).unwrap();
    assert_eq!(
        openmetrics.finish(),
        "# TYPE api_request_duration_seconds counter\n\
         # UNIT api_request_duration_seconds seconds\n\
         api_request_duration_seconds_total 1\n\
         # EOF\n"
    );

    let mut classic = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut classic).unwrap();
    let classic = classic.finish();
    assert_eq!(
        classic,
        "# TYPE api_request_duration_seconds_total counter\napi_request_duration_seconds_total 1\n"
    );
}

/// A label set with a fixed vocabulary, usable as either a fixed or dynamic set.
struct Words(&'static [&'static str]);

impl measured::label::LabelSet for Words {
    type Value<'a> = &'a str;

    fn dynamic_cardinality(&self) -> std::option::Option<usize> {
        Some(self.0.len())
    }

    fn encode(&self, value: &str) -> std::option::Option<usize> {
        self.0.iter().position(|w| *w == value)
    }

    fn decode(&self, value: usize) -> &str {
        self.0[value]
    }
}

impl measured::label::FixedCardinalitySet for Words {}
impl measured::label::DynamicLabelSet for Words {}

#[derive(LabelGroup)]
#[label(set = PairLabelSet)]
struct PairLabels<'a> {
    #[label(fixed_with = Words)]
    fixed: &'a str,
    #[label(dynamic_with = Words)]
    dynamic: &'a str,
}

#[test]
fn label_set_new_uses_declaration_order() {
    let set = PairLabelSet::new(Words(&["f"]), Words(&["d"]));
    let counter = measured::CounterVec::with_label_set(set);
    counter.inc(PairLabels { fixed: "f", dynamic: "d" });

    let mut enc = BufferedTextEncoder::new();
    counter
        .collect_family_into(
            measured::metric::name::MetricName::from_str("pairs"),
            measured::metric::group::FamilyMeta::new(),
            &mut enc,
        )
        .unwrap();
    let s = String::from_utf8(enc.finish().to_vec()).unwrap();
    assert!(s.contains("pairs{fixed=\"f\",dynamic=\"d\"} 1\n"), "{s}");
}

#[derive(LabelGroup)]
#[label(set = RawLabelSet)]
struct RawLabels {
    r#type: Method,
}

#[derive(MetricGroup)]
#[metric(new())]
struct RawMetrics {
    r#in_flight: measured::CounterVec<RawLabelSet>,
}

#[test]
fn raw_identifiers() {
    let metrics = RawMetrics::new();
    metrics.r#in_flight.inc(RawLabels { r#type: Method::Get });

    let mut enc = BufferedTextEncoder::new();
    metrics.collect_group_into(&mut enc).unwrap();
    let s = String::from_utf8(enc.finish().to_vec()).unwrap();
    assert!(s.contains("in_flight{type=\"get\"} 1\n"), "{s}");
}

#[test]
fn raw_enum_variants_use_the_unprefixed_label_value() {
    #[allow(non_camel_case_types)]
    #[derive(Clone, Copy, FixedCardinalityLabel)]
    enum Raw {
        r#type,
    }
    #[derive(LabelGroup)]
    #[label(set = Labels)]
    struct LabelsValue {
        kind: Raw,
    }
    let counter = measured::CounterVec::<Labels>::new();
    counter.inc(LabelsValue { kind: Raw::r#type });
    let mut enc = BufferedTextEncoder::new();
    counter
        .collect_family_into(
            measured::metric::name::MetricName::from_str("raw"),
            measured::metric::group::FamilyMeta::new(),
            &mut enc,
        )
        .unwrap();
    assert_eq!(enc.finish(), "# TYPE raw counter\nraw{kind=\"type\"} 1\n");
}
